<script setup lang="ts">import{ref}from'vue';import{useRoute,useRouter}from'vue-router';import{command}from'../firebase';const route=useRoute(),router=useRouter();const name=ref(localStorage.name||''),code=ref(String(route.params.code||'')),busy=ref(false),error=ref('');async function go(kind:'createRoom'|'joinRoom'){try{busy.value=true;error.value='';localStorage.name=name.value;const r=await command<{roomId:string}>(kind,{name:name.value.trim(),code:code.value.toUpperCase()});router.push(`/room/${r.roomId}`)}catch(e:any){error.value=e.message}finally{busy.value=false}}</script>
<template><section class="hero"><div class="eyebrow">ECHTE KARTEN · DIGITALE CHIPS</div><h1>Der Pokerabend.<br><em>Ohne Chipkoffer.</em></h1><p>Stacks, Einsätze und Pots für bis zu neun Personen – live auf jedem Smartphone.</p><div class="join-card"><label>Dein Anzeigename<input v-model="name" maxlength="24" autocomplete="nickname" placeholder="z. B. Alex"></label><button :disabled="!name.trim()||busy" @click="go('createRoom')">Neuen Tisch eröffnen <b>→</b></button><div class="or"><span>oder beitreten</span></div><div class="join"><input v-model="code" maxlength="6" placeholder="RAUMCODE" autocapitalize="characters"><button class="secondary" :disabled="!name.trim()||code.length!==6||busy" @click="go('joinRoom')">Beitreten</button></div><p class="error" role="alert">{{error}}</p></div><div class="features"><span>◆ Keine Registrierung</span><span>◆ Sicher synchronisiert</span><span>◆ Für 2–9 Spieler</span></div></section></template>
